func checkpointGuardOwned(path string) bool {
	switch path {
	case checkpointGuardExclusive, checkpointGuardShared, checkpointGuardPublish, checkpointGuardPagerWords, checkpointGuardPagerDefault, checkpointGuardPagerAdapter, checkpointGuardRootWords, checkpointGuardRootDefault, checkpointGuardRootAdapter, checkpointGuardModel, checkpointGuardModelTest, checkpointGuardLedger, checkpointGuardLedgerTest, checkpointGuardBridge, checkpointGuardNative:
		return true
	}
	return false
}
func checkpointGuardProduction(path string) bool {
	return path == checkpointGuardExclusive || path == checkpointGuardShared || path == checkpointGuardPublish
}
func checkpointGuardManual(path string) bool {
	return path == checkpointGuardPagerAdapter || path == checkpointGuardRootAdapter || path == checkpointGuardBridge || path == checkpointGuardNative
}
func checkpointGuardPure(path string) bool {
	return path == checkpointGuardModel || path == checkpointGuardModelTest || path == checkpointGuardLedger || path == checkpointGuardLedgerTest
}
func checkpointGuardProtected(name string) bool {
	switch name {
	case "ManualFrameLimit", "ManualFrameCount", "ManualExitCode", "ManualFixture", "ManualBinding", "ManualPage", "ManualRoot", "ManualObservation", "ManualHead", "ManualFrame", "ManualCase", "ManualChannel", "ManualChildChannel", "ManualEncodeFrame", "ManualDecodeFrame", "ManualReadFrame", "ManualWriteFrame", "ManualContext", "ManualArmed", "ManualAbort", "ManualPageObserve", "ManualRootValid", "ManualRootObserve", "ManualReturnedNil", "ManualModelHeader", "ManualModelObservation", "manualBindingValid", "manualFailedChannels", "manualContextKey", "manualScope", "manualBarrier", "manualAbortCode":
		return true
	}
	return strings.HasPrefix(name, "manualCheckpoint") || strings.HasPrefix(name, "TestManualCheckpointRestart") || strings.HasPrefix(name, "checkpointPublication") || strings.HasPrefix(name, "checkpointExclusive") || strings.HasPrefix(name, "checkpointShared") || strings.HasPrefix(name, "checkpointBeforeRoot") || strings.HasPrefix(name, "checkpointAfterRoot") || name == "checkpointObserve" || name == "checkpointPoint"
}
func checkpointGuardImportSet(path string) map[string]bool {
	return encryptedRootSet(checkpointGuardImports[path])
}

func inspectCheckpointRestartStructure(path string, raw []byte) ([]string, error) {
	path = filepath.ToSlash(filepath.Clean(path))
	set := token.NewFileSet()
	file, err := parser.ParseFile(set, path, raw, parser.ParseComments)
	if err != nil {
		return nil, err
	}
	var findings []string
	report := func(message string) { findings = append(findings, path+": checkpoint restart: "+message) }
	owned, manual, pure := checkpointGuardOwned(path), checkpointGuardManual(path), checkpointGuardPure(path)
	guard := path == checkpointGuardSource || path == checkpointGuardTest
	defaultStub := path == checkpointGuardPagerDefault || path == checkpointGuardRootDefault
	words := path == checkpointGuardPagerWords || path == checkpointGuardRootWords
	if strings.HasPrefix(path, "internal/pager/checkpoint_observation") || strings.HasPrefix(path, "internal/pager/checkpoint_restart") || strings.HasPrefix(path, "internal/encstore/checkpoint_observation") || strings.HasPrefix(path, "internal/encstore/checkpoint_restart") || strings.HasPrefix(path, "internal/testkit/checkpointrestart/") || strings.HasPrefix(path, "sqlite/checkpoint_restart") {
		if !owned {
			report("source inventory expanded")
		}
	}
	first := strings.SplitN(string(raw), "\n", 2)[0]
	for _, group := range file.Comments {
		for _, comment := range group.List {
			if owned && strings.HasPrefix(comment.Text, "//go:") && !strings.HasPrefix(comment.Text, "//go:build ") {
				report("compiler directive outside finite source contract")
			}
			if strings.HasPrefix(comment.Text, "//go:build") || strings.HasPrefix(comment.Text, "// +build") {
				if strings.Contains(comment.Text, "manual_checkpoint_restart") && !manual && !defaultStub {
					report("manual tag outside exact closure")
				}
				if owned && ((!manual && !defaultStub) || strings.HasPrefix(comment.Text, "// +build")) {
					report("unapproved build constraint")
				}
			}
		}
	}
	if manual && (first != checkpointGuardTag || strings.Count(string(raw), "//go:build") != 1) {
		report("exact Linux AND manual tag required")
	}
	if defaultStub && (first != checkpointGuardDefaultTag || strings.Count(string(raw), "//go:build") != 1) {
		report("exact default/non-Linux complement required")
	}
	if owned {
		want := "checkpointrestart"
		if strings.HasPrefix(path, "internal/pager/") {
			want = "pager"
		}
		if strings.HasPrefix(path, "internal/encstore/") {
			want = "encstore"
		}
		if path == checkpointGuardNative {
			want = "sqlite_test"
		}
		if file.Name.Name != want {
			report("package identity changed")
		}
	}
	imports := map[string]string{}
	for _, imp := range file.Imports {
		value, e := strconv.Unquote(imp.Path.Value)
		if e != nil {
			return findings, e
		}
		name := filepath.Base(value)
		if imp.Name != nil {
			name = imp.Name.Name
		}
		imports[name] = value
		if value == checkpointGuardImport && (imp.Name != nil || path != checkpointGuardPagerAdapter && path != checkpointGuardRootAdapter && path != checkpointGuardNative) {
			report("checkpoint consumer outside exact closure")
		}
		if owned && !checkpointGuardProduction(path) && (imp.Name != nil || !checkpointGuardImportSet(path)[value]) {
			report("import capability expanded")
		}
	}
	if owned && !checkpointGuardProduction(path) && len(file.Imports) != len(checkpointGuardImportSet(path)) {
		report("exact import inventory changed")
	}
	parents := oracleParents(file)
	functions := readOnlyWALManualFunctions(file)
	ast.Inspect(file, func(node ast.Node) bool {
		if id, ok := node.(*ast.Ident); ok && checkpointGuardProtected(id.Name) && !owned && !guard {
			report("capability reference outside exact closure")
		}
		if !owned || checkpointGuardProduction(path) {
			return true
		}
		switch n := node.(type) {
		case *ast.FuncDecl:
			if n.Name.Name == "init" || n.Name.Name == "TestMain" || n.Body == nil {
				report("initializer or external implementation forbidden")
			}
		case *ast.GoStmt, *ast.SendStmt, *ast.ChanType:
			if pure || defaultStub || words {
				report("inert source cannot acquire channel effects")
			}
		case *ast.GenDecl:
			if n.Tok == token.VAR && pure {
				if _, top := parents[n].(*ast.File); top {
					report("model package state forbidden")
				}
			}
		case *ast.FuncType:
			if _, declaration := parents[n].(*ast.FuncDecl); !declaration && (defaultStub || words || path == checkpointGuardPagerAdapter || path == checkpointGuardRootAdapter) {
				report("observer callback forbidden")
			}
		case *ast.SelectorExpr:
			if q, ok := n.X.(*ast.Ident); ok && imports[q.Name] == checkpointGuardImport && strings.HasPrefix(n.Sel.Name, "Manual") {
				call, direct := parents[n].(*ast.CallExpr)
				// Value transport types are allowed; function bodies and complete
				// declarations remain frozen below, including this exact use.
				if encryptedRootSet("ManualContext ManualReturnedNil ManualArmed ManualPageObserve ManualRootObserve ManualAbort ManualChildChannel ManualReadFrame ManualWriteFrame ManualCase")[n.Sel.Name] && (!direct || call.Fun != n) {
					report("manual operation alias or callback forbidden")
				}
			}
			switch n.Sel.Name {
			case "Kill", "Signal", "CommandContext", "StartProcess", "ForkExec", "RecoverRollback", "RollbackRecovery", "WALTailPublication", "Normalize", "Reindex", "Rekey", "Remove", "RemoveAll", "Rename", "Symlink", "Link", "Truncate", "Chmod", "Chdir", "Setenv", "Fd", "SyscallConn", "RawConn", "TempDir", "Parallel":
				report("forbidden effect or ownership bypass: " + n.Sel.Name)
			case "Command", "Start", "Wait", "Exit":
				call, direct := parents[n].(*ast.CallExpr)
				if !direct || call.Fun != n || !checkpointGuardProcessCall(path, call, parents, set, raw) {
					report("process capability outside exact owned site")
				}
			}
		}
		return true
	})
	if words && (len(functions) != 0 || len(file.Imports) != 0) {
		report("private scalar vocabulary must be inert")
	}
	if defaultStub {
		name, signature := "checkpointObserve", `func checkpointObserve(context.Context, checkpointPoint, string, uint32, uint32, uint32, uint32, [2]uint32, [2]uint32, uint32, uint32) {}`
		if path == checkpointGuardRootDefault {
			name, signature = "checkpointPublicationObserve", `func checkpointPublicationObserve(context.Context, checkpointPublicationPoint, string, []byte, []byte) {}`
		}
		fn := functions[name]
		if len(functions) != 1 || fn == nil || rekeyGuardText(set, raw, fn) != encryptedRootCompact(signature) {
			report("ordinary observer must be exactly empty and void")
		}
	}
	if checkpointGuardProduction(path) {
		findings = append(findings, checkpointGuardProductionOrder(path, raw, set, file)...)
	}
	if path == checkpointGuardMain {
		findings = append(findings, inspectReadOnlyWALManualWiring(raw)...)
		findings = append(findings, rekeyGuardMainSemantics(path, raw, set, file)...)
	}
	// Complete finite function/type/declaration closure. This is token-level
	// source identity, independent of the byte pin; comments and spacing normalize.
	// Repinned mutants below exercise these frozen operations, not old hashes.
	if expected, ok := checkpointGuardTemplates[path]; ok {
		findings = append(findings, rollbackFaultDeclarationShape(path, raw, set, file, expected)...)
	} else if owned || path == checkpointGuardMain || path == checkpointGuardOracle {
		report("finite source template HOLD")
	}
	return findings, nil
}

func checkpointGuardProductionOrder(path string, raw []byte, set *token.FileSet, file *ast.File) []string {
	var findings []string
	fail := func() {
		findings = append(findings, path+": checkpoint restart: exact void observation adjacency/order required")
	}
	parents := oracleParents(file)
	observer, owner, want := "checkpointObserve", "checkpointLocked", 2
	if path == checkpointGuardShared {
		owner = "checkpointLocked"
	}
	if path == checkpointGuardPublish {
		observer, owner, want = "checkpointPublicationObserve", "publishRoot", 3
	}
	count := 0
	ast.Inspect(file, func(node ast.Node) bool {
		id, ok := node.(*ast.Ident)
		if !ok || id.Name != observer {
			return true
		}
		count++
		call, direct := parents[id].(*ast.CallExpr)
		statement, standalone := parents[call].(*ast.ExprStmt)
		fn := oracleEnclosingFunction(id, parents)
		if !direct || call.Fun != id || !standalone || statement.X != call || fn == nil || fn.Name.Name != owner {
			fail()
		}
		return true
	})
	if count != want {
		fail()
	}
	found := 0
	ast.Inspect(file, func(node ast.Node) bool {
		block, ok := node.(*ast.BlockStmt)
		if !ok {
			return true
		}
		switch path {
		case checkpointGuardExclusive:
			if rekeyGuardSequence(block, set, raw,
				`if err := writeFullAt(s.file, p, int64(n-1)*int64(s.header.PageSize)); err != nil { return fail(err) }`,
				`checkpointObserve(ctx, checkpointExclusiveCopy, s.path, n, uint32(len(pages)), s.snapshot.DBSize, s.snapshot.FrameCount, s.snapshot.Header.Salt, [2]uint32(s.snapshot.Checksum), 0, 0)`) {
				found++
			}
			if rekeyGuardSequence(block, set, raw,
				`if err := os.Remove(s.path + "-wal"); err != nil { return fail(err) }`,
				`checkpointObserve(ctx, checkpointExclusiveRetired, s.path, 0, uint32(len(s.snapshot.Pages)), s.snapshot.DBSize, s.snapshot.FrameCount, s.snapshot.Header.Salt, [2]uint32(s.snapshot.Checksum), 0, 0)`,
				`if err := os.Remove(s.path + "-shm"); err != nil && !os.IsNotExist(err) { return fail(err) }`) {
				found++
			}
		case checkpointGuardShared:
			if rekeyGuardSequence(block, set, raw,
				`if err = writeFullAt(s.file, page, int64(n-1)*int64(h.PageSize)); err != nil { return fail(err) }`,
				`checkpointObserve(ctx, checkpointSharedCopy, s.path, n, uint32(len(images)), h.DBSize, h.MaxFrame, [2]uint32{binary.BigEndian.Uint32(h.Salt[:4]), binary.BigEndian.Uint32(h.Salt[4:])}, h.FrameChecksum, safe, backfill)`) {
				found++
			}
			if rekeyGuardSequence(block, set, raw,
				`if err = s.file.Sync(); err != nil { return fail(err) }`,
				`if err = s.index.SetBackfill(safe); err != nil { return fail(sharedIndexError(err)) }`,
				`checkpointObserve(ctx, checkpointSharedBackfill, s.path, 0, uint32(len(images)), h.DBSize, h.MaxFrame, [2]uint32{binary.BigEndian.Uint32(h.Salt[:4]), binary.BigEndian.Uint32(h.Salt[4:])}, h.FrameChecksum, safe, backfill)`,
				`if safe < h.MaxFrame { return ErrBusy }`) {
				found++
			}
		case checkpointGuardPublish:
			if rekeyGuardSequence(block, set, raw,
				`rekeyPublicationObserve(ctx, rekeyBeforeRootRename, s.path, s.rootBytes, raw)`,
				`checkpointPublicationObserve(ctx, checkpointBeforeRootRename, s.path, s.rootBytes, raw)`,
				`attempted = true`,
				`if e = s.ns.rename(pending, s.path, len(s.rootBytes) == 0); e != nil { return uncertain(e) }`,
				`rekeyPublicationObserve(ctx, rekeyAfterRootRename, s.path, s.rootBytes, raw)`,
				`checkpointPublicationObserve(ctx, checkpointAfterRootRename, s.path, s.rootBytes, raw)`,
				`if e = s.ns.sync(s.path); e != nil { return uncertain(e) }`,
				`rekeyPublicationObserve(ctx, rekeyAfterRootDirSync, s.path, s.rootBytes, raw)`,
				`checkpointPublicationObserve(ctx, checkpointAfterRootDirSync, s.path, s.rootBytes, raw)`,
				`root, ri, e := s.ns.checked(s.path, os.O_RDONLY)`) {
				found += 3
			}
		}
		return true
	})
	if found != want {
		fail()
	}
	return findings
}

func checkpointGuardProcessCall(path string, call *ast.CallExpr, parents map[ast.Node]ast.Node, set *token.FileSet, raw []byte) bool {
	if path == checkpointGuardNative && rekeyGuardText(set, raw, call) == encryptedRootCompact(`command.Wait()`) {
		// Wait is a single owned goroutine inside the original non-nil process
		// branch. Nested functions elsewhere never inherit a blanket exemption.
		var launch *ast.GoStmt
		for n := ast.Node(call); n != nil; n = parents[n] {
			if g, ok := n.(*ast.GoStmt); ok {
				launch = g
				break
			}
		}
		if launch == nil || rekeyGuardText(set, raw, launch) != encryptedRootCompact(`go func() { err := command.Wait(); child.wait <- manualCheckpointWait{State: command.ProcessState, Err: err} }()`) {
			return false
		}
		block, ok := parents[launch].(*ast.BlockStmt)
		if !ok {
			return false
		}
		branch, ok := parents[block].(*ast.IfStmt)
		if !ok || rekeyGuardText(set, raw, branch.Cond) != encryptedRootCompact(`command.Process != nil`) {
			return false
		}
		fn := oracleEnclosingFunction(branch, parents)
		return fn != nil && fn.Name.Name == "start" && fn.Recv != nil && len(fn.Recv.List) == 1 && rekeyGuardText(set, raw, fn.Recv.List[0]) == encryptedRootCompact(`r *manualCheckpointRun`)
	}
	key := rekeyGuardCallContext(path, call, parents, set, raw)
	for _, allowed := range []string{
		checkpointGuardNative + `|start|exec.Command(r.admission.BinaryPath, manualCheckpointFlags(role)...)`,
		checkpointGuardNative + `|start|command.Start()`,
		checkpointGuardBridge + `|manualBarrier|os.Exit(ManualExitCode)`,
		checkpointGuardBridge + `|ManualAbort|os.Exit(manualAbortCode)`,
	} {
		parts := strings.SplitN(allowed, "|", 3)
		if key == parts[0]+"|"+parts[1]+"|"+encryptedRootCompact(parts[2]) {
			return true
		}
	}
	return false
}

// Sole startup admission: this exact file, tag, import, direct same-image call,
// flags, controller-only role and complete finite source contract. HOLD refuses.
func checkpointGuardProcessReference(path string, selector *ast.SelectorExpr, parents map[ast.Node]ast.Node, set *token.FileSet, raw []byte) bool {
	if filepath.ToSlash(filepath.Clean(path)) != checkpointGuardNative || strings.SplitN(string(raw), "\n", 2)[0] != checkpointGuardTag || selector.Sel.Name != "Command" {
		return false
	}
	q, ok := selector.X.(*ast.Ident)
	if !ok || q.Name != "exec" {
		return false
	}
	call, ok := parents[selector].(*ast.CallExpr)
	if !ok || call.Fun != selector || !checkpointGuardProcessCall(path, call, parents, set, raw) {
		return false
	}
	var file *ast.File
	for n := ast.Node(selector); n != nil; n = parents[n] {
		if f, ok := n.(*ast.File); ok {
			file = f
			break
		}
	}
	if file == nil || !restartGuardImportBound(file, "exec", "os/exec") || readOnlyWALManualCountCall(file, "exec.Command") != 1 {
		return false
	}
	got, err := inspectCheckpointRestartSource(path, raw)
	return err == nil && len(got) == 0
}

func inspectCheckpointRestartSource(path string, raw []byte) ([]string, error) {
	findings, err := inspectCheckpointRestartStructure(path, raw)
	if err != nil {
		return findings, err
	}
	path = filepath.ToSlash(filepath.Clean(path))
	if pin, ok := checkpointGuardPins[path]; ok && fmt.Sprintf("%x", sha256.Sum256(raw)) != pin {
		findings = append(findings, path+": checkpoint restart full-source review HOLD/mismatch")
	}
	return findings, nil
}
func inspectCheckpointRestartContracts(root string) ([]string, error) {
	var findings []string
	seen := map[string]bool{}
	err := filepath.WalkDir(root, func(path string, entry fs.DirEntry, walkErr error) error {
		if walkErr != nil {
			return walkErr
		}
		if entry.IsDir() {
			if entry.Name() == ".git" {
				return filepath.SkipDir
			}
			return nil
		}
		rel, err := filepath.Rel(root, path)
		if err != nil {
			return err
		}
		rel = filepath.ToSlash(rel)
		if !oracleCurrentGoPath(rel) && rel != checkpointGuardDoc {
			return nil
		}
		raw, err := os.ReadFile(path)
		if err != nil {
			return err
		}
		seen[rel] = true
		if rel == checkpointGuardDoc {
			if fmt.Sprintf("%x", sha256.Sum256(raw)) != checkpointGuardPins[rel] {
				findings = append(findings, rel+": checkpoint restart full-source review HOLD/mismatch")
			}
			return nil
		}
		got, err := inspectCheckpointRestartSource(rel, raw)
		if err != nil {
			return err
		}
		findings = append(findings, got...)
		return nil
	})
	if err != nil {
		return findings, err
	}
	for path := range checkpointGuardPins {
		if !seen[path] {
			findings = append(findings, path+": checkpoint restart required source missing")
		}
	}
	if !seen[checkpointGuardSource] || !seen[checkpointGuardTest] {
		findings = append(findings, "checkpoint restart guard inventory missing")
	}
	return findings, nil
}

